"""Remaining measured inline, text and image leaves. Author one leaf before its sheet review."""
from write_elements import write
import sys

COPY='운영 담당자는 최근 접수된 문의를 채널별로 분류하고 처리 소요 시간을 대조했습니다. 검토 결과 반복 발생 항목에 인력을 우선 배정하기로 합의했습니다. 다음 배포에서는 승인 내역과 변경 사유를 기록해 인수 담당자가 이력을 확인할 수 있도록 합니다.'

def author(k):
 if k=='headline':write(k,'headline','''/* Replica12:155×35 dark capsule kick above a30px two-line statement.
Replica05/11 provide plain and centred subheads; big is an inferred statement variant. */
ROOT{container-type:size;container-name:od-headline;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;gap:calc(var(--gap-sm)*9/14);min-width:0;min-height:0;color:var(--ink)}
ROOT:has(>.kick):not(.big):not(.on){inline-size:min(100%,380px)}ROOT>.kick{margin:0;inline-size:min(100%,155px);min-block-size:35px;display:inline-flex;align-items:center;justify-content:center;background:var(--n-9);color:var(--page);border-radius:999px;padding:0 var(--gap-sm);font-size:clamp(var(--type-12),calc(4.737cqw),var(--type-18));font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);text-align:center}ROOT.on>.kick{inline-size:auto;max-width:100%;white-space:nowrap}
ROOT>h2{margin:0;font-size:clamp(var(--type-18),calc(8cqw),var(--type-30));font-weight:var(--lead-weight);line-height:var(--onboard-docket-statement-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}ROOT>h2>b{font-weight:var(--title-weight);color:var(--a1-7)}ROOT>.note{margin:0;font-size:var(--type-16);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7);overflow-wrap:anywhere}
ROOT:not(:has(>.kick))>h2{line-height:var(--body-line);font-size:clamp(var(--type-20),calc(4cqw),var(--type-24));font-weight:var(--name-weight);color:var(--a1-7)}ROOT.big>h2{font-size:clamp(var(--type-28),calc(6cqw),var(--type-48));font-weight:var(--title-weight);color:var(--a1-7)}ROOT.center{align-items:center;text-align:center}ROOT.center>h2{font-size:clamp(var(--type-14),calc(3cqw),var(--type-18));font-weight:var(--name-weight);color:var(--a1-7)}ROOT.on{background:var(--a1-7);color:var(--page);padding:2%}ROOT.on>h2,ROOT.on>h2>b,ROOT.on>.note{color:var(--page)}
@container od-headline (max-height:100px){ROOT>.kick{font-size:var(--type-12);padding:calc(var(--gap-sm)/3) var(--gap-sm)}ROOT:has(>.kick)>h2{font-size:var(--type-20)}ROOT>.note{display:none}}
@container od-headline (max-width:320px){ROOT>.kick{font-size:var(--type-12)}ROOT>h2{font-size:var(--type-18)}ROOT>.note{font-size:var(--type-12)}}
''','A dark, one-line capsule labels a restrained statement. Its open space and line rhythm are measured from replica12. Big emphasis and centred subheads change hierarchy without introducing a second decorative system.',[('replica-12','4x3','<div class="headline" DATA><p class="kick">WORK POLICY</p><h2>접수 채널을 연결해<br>이관 근거를 명확히 남깁니다.</h2></div>'),('replica-05','4x3','<div class="headline" DATA><h2>이번 배포의 <b>승인 기준</b>을 정리합니다.</h2></div>'),('replica-11','4x2','<div class="headline center" DATA><h2>채널별 접수 기록과 처리 원칙</h2></div>'),('long-on','4x4','<div class="headline on" DATA><p class="kick">OPERATIONS REVIEW</p><h2>지연 발생 원인을 부서별로 나누고 <b>우선 조치 항목</b>을 확정합니다.</h2><p class="note">월간 점검 회의에서 승인된 사항을 함께 기록합니다.</p></div>')])
 elif k=='prose':write(k,'prose','''/* Replica05:19px running copy with1.6 line spacing;16px accent follow-up.
Replica06/12:14px secondary passages. */
ROOT{container-type:size;container-name:od-prose;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:center;gap:var(--gap-sm);min-width:0;min-height:0;color:var(--n-8)}ROOT>p{grid-column:1 / -1;margin:0;font-size:clamp(var(--type-14),calc(3cqw),var(--type-20));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}ROOT>p>b{font-weight:var(--name-weight);color:var(--ink)}ROOT.lead>p{font-size:clamp(var(--type-14),calc(2.6cqw),var(--type-16));color:var(--a1-7)}ROOT.quiet>p{font-size:clamp(var(--type-12),calc(2.5cqw),var(--type-14));color:var(--n-7)}ROOT.cols>p{grid-column:span 1}
@container od-prose (max-width:450px){ROOT>p{font-size:var(--type-14)}ROOT.cols>p{grid-column:1 / -1}}@container od-prose (max-height:180px){ROOT>p,ROOT.lead>p,ROOT.quiet>p{font-size:var(--type-12)}}
''','Plain paragraphs preserve the generous leading and slightly tight tracking of replica05. The lead variant carries the accent role and quiet passages step down in hierarchy; columns collapse by moving the actual paragraph children.',[('replica-05','6x3','<div class="prose" DATA><p>'+COPY+'</p></div>'),('replica-05-lead','4x3','<div class="prose lead" DATA><p>검토한 예외 사항은 승인 문서에 남기고, 이관 담당자에게 변경 이유를 전달합니다.</p><p>신규 배포 전에는 접수 채널별 안내 문구와 응답 기준을 대조합니다.</p></div>'),('replica-06','4x3','<div class="prose quiet" DATA><p>개선 요청이 몰리는 시간대와 고객 채널을 대조해 담당 인력을 배정합니다.</p></div>'),('replica-12','6x4','<div class="prose quiet" DATA><p>담당 조직은 지난 분기 접수 기록을 대조하며 처리 기한이 지연된 원인을 분류했습니다. 안내 문구와 승인 절차가 서로 다른 구간은 같은 기준으로 정비합니다.<br><br>이번 배포에서는 이관 담당자가 변경 사유를 확인할 수 있도록 승인 내역과 근거 문서를 연결합니다. 예외 요청은 별도 기록해 다음 점검에서 처리 경과를 다시 살핍니다.<br>운영 책임자는 현장의 질문을 모아 담당자 협의 결과와 함께 공유합니다.</p></div>'),('two-paragraphs','6x4','<div class="prose cols" DATA><p>'+COPY.split(' 다음')[0]+'</p><p>승인 책임자는 변경 요청을 분야별로 검토한 뒤 예외 항목을 정리합니다. 이력이 누락된 건은 담당 조직에 되돌려 근거를 보완하도록 안내합니다.</p></div>')])
 elif k=='pill':write(k,'pill','''/* Replica06:101×30 dark capsule with a16px centred word; accent and quiet colour roles. */
ROOT{container-type:size;container-name:od-pill;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0}ROOT>.parts{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:calc(var(--gap-sm)/2);max-width:100%;padding:calc(var(--gap-sm)/3) clamp(calc(var(--gap-sm)/3),calc((100cqw - 48px)/2),calc(var(--pad)*1.1));border-radius:999px;background:var(--n-9);color:var(--page)}ROOT>.parts>.name{margin:0;font-size:clamp(var(--type-12),calc(15.84cqw),var(--type-16));font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--label-track);overflow-wrap:anywhere;text-align:center}ROOT>.parts>.note{margin:0;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);text-align:center}ROOT>.parts>.mark{width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:var(--type-14)}ROOT>.parts>.mark>.icon{width:55%;height:55%}ROOT>.parts>.mark>.icon>svg{width:100%;height:100%}ROOT.on>.parts{background:var(--a1);color:var(--a1-on)}ROOT.quiet>.parts{background:var(--a2-7);color:var(--page)}ROOT.line>.parts{background:var(--page);color:var(--ink);border:var(--stroke) solid var(--n-4)}@container od-pill (max-width:550px){ROOT>.parts>.note{display:none}}@container od-pill (max-height:90px){ROOT>.parts>.note{display:none}}@container od-pill (max-width:300px){ROOT>.parts:has(>.mark){padding:calc(var(--gap-sm)/3) var(--gap-sm)}ROOT>.parts:has(>.mark)>.name{font-size:var(--type-14)}}
''','A compact dark capsule centres a single business label. Its horizontal inset and vertical leading derive from the101×30 label in replica06; mark and note remain part of the same wrapping capsule.',[('replica-06','2x1','<div class="pill" DATA><div class="parts"><p class="name">신뢰성</p></div></div>'),('replica-06-on','2x1','<div class="pill on" DATA><div class="parts"><p class="name">정확성</p></div></div>'),('replica-06-quiet','2x1','<div class="pill quiet" DATA><div class="parts"><p class="name">협업성</p></div></div>'),('long-line','3x2','<div class="pill line" DATA><div class="parts"><span class="mark"><span class="icon" data-icon="shield-check"></span></span><p class="name">이관 승인 담당자 협의</p><p class="note">운영 책임자의 검토가 진행 중입니다.</p></div></div>')])
 elif k=='callout':write(k,'callout','''/* Replica06:1083×48 quiet conclusion capsule,21px text at its optical centre. */
ROOT{container-type:size;container-name:od-callout;display:flex;align-items:center;justify-content:center;gap:var(--gap-sm);min-width:0;min-height:0;color:var(--n-8)}ROOT>p{margin:0;width:100%;border-radius:999px;background:var(--n-1);padding:calc(var(--gap-sm)*.7) var(--pad);font-size:clamp(var(--type-14),calc(1.939cqw),var(--type-22));font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);text-align:center;overflow-wrap:anywhere}ROOT>p>b{font-weight:var(--name-weight)}ROOT>.icon{width:40px;height:40px;color:var(--a1);flex:none}ROOT>.icon>svg{width:100%;height:100%}@container od-callout (max-width:450px){ROOT>p{font-size:var(--type-14);padding:var(--gap-sm)}}@container od-callout (max-height:45px){ROOT>p{font-size:var(--type-12);padding:calc(var(--gap-sm)/2) var(--gap-sm)}ROOT>.icon{width:24px;height:24px}}
''','A quiet, fully rounded conclusion band uses the measured48px optical height of replica06. The optional icon precedes the sentence and bold fragments identify the conclusion inside the neutral capsule.',[('replica-06','6x2','<div class="callout" DATA><p>검토 이력을 연결해 담당 조직의 승인 근거를 명확히 남깁니다.</p></div>'),('long-icon','4x3','<div class="callout" DATA><span class="icon" data-icon="check"></span><p>반복 문의를 줄이기 위해 <b>접수 분류와 이관 기준</b>을 함께 정비합니다.</p></div>')])
 elif k=='tag':write(k,'tag','''/* Replica12:155×35 dark inline label. The inline highlight is the dark paper strip in replica04. */
ROOT{container-type:size;display:flex;align-items:center;justify-content:center;justify-self:start;align-self:center;inline-size:min(100%,155px);block-size:min(100%,35px);padding:0 var(--gap-sm);border-radius:999px;background:var(--n-9);color:var(--page);font-size:var(--type-18);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);text-align:center;overflow-wrap:anywhere}
.hl[data-el="onboard-docket-tag"]{container-type:size;display:inline;padding:0 calc(var(--pad)/2);background:var(--ink);color:var(--page);font-size:inherit;font-weight:var(--body-weight);line-height:inherit;letter-spacing:inherit}
''','The155×35 inline label is a dark capsule with a centred line. A running highlight uses the dark label surface role without drawing a new shape around a whole paragraph.',[('replica-12','2x1','<span class="tag" DATA>운영 원칙</span>'),('review-label','2x1','<span class="tag" DATA>이관 검토</span>'),('replica-04-highlight','6x4','<div class="quote" data-el="onboard-docket-quote" style="grid-column:1 / span 12;grid-row:1 / span 6"><blockquote><p>현장의 의견과 운영 경험을 연결해<br><span class="hl" data-el="onboard-docket-tag">합의한 운영 기준을 문서로 남깁니다.</span></p></blockquote><div class="by"><p class="name">운영 책임　윤서진</p></div></div>')])
 elif k=='image-frame':write(k,'frame','''/* Replica18:493×330 plain picture seat; the receiving box may crop an image.
Portrait is an inferred media child; the out-of-body source04 placement is a gap. */
ROOT{container-type:size;container-name:od-frame;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0}ROOT>.seat{display:flex;align-items:center;justify-content:center;inline-size:min(100%,calc(100cqh * 493 / 330),628px);block-size:min(100%,420px);aspect-ratio:auto;max-block-size:100%;min-width:0;min-height:0;background:var(--n-2);border:var(--stroke) solid var(--n-3);color:var(--n-7);font-size:var(--type-18);font-weight:var(--label-weight);line-height:var(--label-line)}ROOT>.seat.portrait{inline-size:min(100%,calc(100cqh * 400 / 608),400px);block-size:auto;aspect-ratio:400 / 608}ROOT>.seat.avatar{inline-size:min(100%,100cqh,330px);block-size:auto;aspect-ratio:1;border-radius:50%}
''','A plain, thin-edged seat fills the receiving image rectangle, with a width ceiling proportional to the493:330 media field of replica18. Portrait and avatar children retain their own aspect. The source04 portrait extending above the body is explicitly unexpressible as a page placement.',[('replica-18','3x3','<div class="frame" DATA><div class="seat" data-ph="1"></div></div>'),('replica-04-portrait','3x3','<div class="frame" DATA><div class="seat portrait" data-ph="2"></div></div>')])
 elif k=='quote':write(k,'quote','''/* Replica04:35px opening quote,17px letter copy and19px signature. */
ROOT{container-type:size;container-name:od-quote;inline-size:min(100%,632px);block-size:min(100%,396px);justify-self:center;align-self:center;display:flex;flex-direction:column;justify-content:center;gap:var(--gap);min-width:0;min-height:0;color:var(--ink)}ROOT>blockquote{position:relative;margin:0;padding:0 3.956cqw 0 7.437cqw}ROOT>blockquote::before,ROOT>blockquote::after{position:absolute;font-size:var(--type-48);line-height:var(--figure-line);font-weight:var(--figure-weight);color:var(--n-8)}ROOT>blockquote::before{content:'“';left:0;top:0}ROOT>blockquote::after{content:'”';right:0;top:1.3em}ROOT>blockquote>p{margin:0;font-size:clamp(var(--type-14),calc(2.7cqw),var(--type-18));font-weight:var(--body-weight);line-height:var(--onboard-docket-letter-line);letter-spacing:var(--body-track)}ROOT>blockquote>p:first-child{font-size:clamp(var(--type-22),calc(5.538cqw),var(--type-36));font-weight:var(--body-weight);line-height:var(--onboard-docket-quote-line);margin-bottom:var(--gap)}ROOT>.by{display:flex;align-items:center;gap:var(--gap-sm);padding-inline:7.437cqw 3.956cqw}ROOT>.by>.name{font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--name-line);letter-spacing:var(--name-track);margin:0}ROOT>.by>.name>span{font-family:var(--onboard-docket-font-signature);font-size:clamp(var(--type-24),calc(5.7cqw),var(--type-36));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track)}ROOT>.by>.note{font-size:var(--type-12);line-height:var(--body-line);color:var(--n-7);margin:0}ROOT>.by>.seat{width:56px;height:56px;flex:none}ROOT.big>blockquote>p:first-child{font-size:clamp(var(--type-24),calc(6cqw),var(--type-44))}@container od-quote (max-width:450px){ROOT>blockquote>p:first-child{font-size:var(--type-24)}ROOT>blockquote>p{font-size:var(--type-12)}ROOT>.by>.name{font-size:var(--type-14)}}@container od-quote (max-height:320px){ROOT>blockquote>p:not(:first-child){display:none}}@container od-quote (max-height:260px){ROOT>blockquote>p:not(:first-child){display:none}ROOT>blockquote>p:first-child{font-size:var(--type-22);margin:0}ROOT>.by>.name>span{font-family:var(--onboard-docket-font-signature);font-size:clamp(var(--type-24),calc(5.7cqw),var(--type-36));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track)}ROOT>.by>.note{display:none}}
''','The opening sentence is bracketed by typographic quote marks, followed by a letter-sized passage and a restrained signature. All three levels come from replica04; compact boxes retain the quotation and author while removing the secondary letter passage.',[('replica-04','6x4','<div class="quote" DATA><blockquote><p>현장의 의견과 운영 경험을 연결해<br><span class="hl" data-el="onboard-docket-tag">합의한 운영 기준을 문서로 남깁니다.</span></p><p>'+COPY+'</p></blockquote><div class="by"><p class="name">운영총괄　<span>윤　서　진</span></p></div></div>'),('short-big','4x3','<div class="quote big" DATA><blockquote><p>검토의 근거를 남기면 다음 결정이 빨라집니다.</p></blockquote><div class="by"><p class="name">품질책임　정하린</p><p class="note">분기 점검 회의</p></div></div>')])
 else:raise SystemExit('unwritten '+k)

if __name__=='__main__':author(sys.argv[1])
